export function renderCreateEnvTemplate(): string {
  return [
    "import { z } from 'zod';",
    "import { config } from 'dotenv';",
    "import path from 'node:path';",
    "import { fileURLToPath } from 'node:url';",
    '',
    '// Resolve monorepo workspace directory',
    'const srcDir = path.dirname(fileURLToPath(import.meta.url));',
    "const workspaceRoot = path.resolve(srcDir, '../../..');",
    '',
    '// Load environment variables from monorepo root .env',
    "config({ path: path.join(workspaceRoot, '.env') });",
    '',
    'function formatZodErrors(errors: z.ZodError): string {',
    '  return errors.issues',
    "    .map((issue) => `  ✖ [${issue.path.join('.')}]: ${issue.message}`)",
    "    .join('\\n');",
    '}',
    '',
    'export function createEnv<T extends z.ZodRawShape | z.ZodObject<any>>(',
    '  name: string,',
    '  schemaOrShape: T,',
    ') {',
    '  const schema =',
    '    schemaOrShape instanceof z.ZodObject',
    '      ? schemaOrShape',
    '      : z.object(schemaOrShape as z.ZodRawShape);',
    '',
    "  const isSkip = process.env.SKIP_ENV_VALIDATION === 'true';",
    '  const parsed = schema.safeParse(process.env);',
    '',
    '  if (!parsed.success && !isSkip) {',
    '    console.error(',
    '      `\\n🚨 [${name} Environment Error] Invalid or missing environment variables:\\n${formatZodErrors(parsed.error)}\\n`,',
    '    );',
    '    throw new Error(`${name} environment variable validation failed.`);',
    '  }',
    '',
    '  const env = (isSkip ? ({} as z.infer<typeof schema>) : parsed.data)!;',
    '  return { env, schema };',
    '}',
    '',
  ].join('\n');
}
